) ENGINE=MyISAM DEFAULT CHARSET=utf8 COMMENT='NPC產生列表';

-- ----------------------------
-- Table structure for npc_teleport
-- ----------------------------
CREATE TABLE `npc_teleport` (
  `action` varchar(100) NOT NULL DEFAULT '',
  `npc_id` int(10) NOT NULL,
  `tele_num` int(1) NOT NULL,
  `check_lv_min` int(10) DEFAULT '0' COMMENT '大于等于该等级条件通过',
  `check_lv_max` int(10) DEFAULT '0' COMMENT '小于等于该等级条件通过',
  `check_map` int(10) unsigned NOT NULL DEFAULT '0',
  `x` int(10) unsigned NOT NULL DEFAULT '0',
  `y` int(10) unsigned NOT NULL DEFAULT '0',
  `map` int(10) unsigned NOT NULL DEFAULT '0',
  `aden` int(10) unsigned NOT NULL DEFAULT '0',
  PRIMARY KEY (`check_map`,`action`),
  KEY `action` (`action`),
  KEY `npc_id` (`npc_id`),
  KEY `check_map` (`check_map`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8 COMMENT='NPC传送';

-- ----------------------------
-- Table structure for polymorph
-- ----------------------------
CREATE TABLE `polymorph` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `name` varchar(255) NOT NULL,
  `db` varchar(255) NOT NULL,
  `polyid` int(11) NOT NULL,
  `minlevel` int(11) NOT NULL,
  `isWeapon` int(1) NOT NULL DEFAULT '0',
  `isHelm` int(1) NOT NULL DEFAULT '0',
  `isEarring` int(1) NOT NULL DEFAULT '0',
  `isNecklace` int(1) NOT NULL DEFAULT '0',
  `isT` int(1) NOT NULL DEFAULT '0',
  `isArmor` int(1) NOT NULL DEFAULT '0',
  `isCloak` int(1) NOT NULL DEFAULT '0',
  `isRing` int(1) NOT NULL DEFAULT '0',
  `isBelt` int(1) NOT NULL DEFAULT '0',
  `isGlove` int(1) NOT NULL DEFAULT '0',
  `isShield` int(1) NOT NULL DEFAULT '0',
  `isBoots` int(1) NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`)
) ENGINE=MyISAM AUTO_INCREMENT=59 DEFAULT CHARSET=utf8;

-- ----------------------------
-- Table structure for server
-- ----------------------------
CREATE TABLE `server` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `gametime` int(10) unsigned NOT NULL DEFAULT '0',
  `objectID` int(10) unsigned NOT NULL DEFAULT '1',
  `etcID` int(10) unsigned NOT NULL DEFAULT '10000000',
  `clanID` int(10) unsigned NOT NULL DEFAULT '1',
  `player_count` int(10) unsigned NOT NULL DEFAULT '0',
  `status` tinyint(1) unsigned NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`)
) ENGINE=MyISAM AUTO_INCREMENT=2 DEFAULT CHARSET=utf8;

-- ----------------------------
-- Table structure for skill_list
-- ----------------------------
CREATE TABLE `skill_list` (
  `skill_id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(45) NOT NULL DEFAULT '',
  `skill_level` int(10) NOT NULL DEFAULT '0',
  `skill_no` int(10) NOT NULL DEFAULT '0',
  `magic` enum('pc','npc') NOT NULL DEFAULT 'pc',
  `mp_consume` int(10) unsigned NOT NULL DEFAULT '0',
  `hp_consume` int(10) unsigned NOT NULL DEFAULT '0',
  `item_consume` int(10) unsigned NOT NULL DEFAULT '0',
  `item_consume_count` int(10) unsigned NOT NULL DEFAULT '0',
  `reuse_delay` int(10) unsigned NOT NULL DEFAULT '0',
  `buff_duration` int(10) unsigned NOT NULL DEFAULT '0',
  `type` varchar(45) NOT NULL DEFAULT '',
  `min_dmg` int(10) NOT NULL DEFAULT '0',
  `max_dmg` int(10) unsigned NOT NULL DEFAULT '0',
  `id` int(10) unsigned NOT NULL DEFAULT '0',
  `cast_gfx` int(10) unsigned NOT NULL DEFAULT '0',
  `range` int(10) unsigned NOT NULL DEFAULT '0',
  `lawful_consume` int(10) unsigned NOT NULL DEFAULT '0',
  `attr` int(10) unsigned NOT NULL DEFAULT '0' COMMENT '屬性',
  PRIMARY KEY (`skill_id`),
  KEY `idx_skill_name` (`name`) USING BTREE
) ENGINE=MyISAM AUTO_INCREMENT=10002 DEFAULT CHARSET=utf8 COMMENT='技能';

-- ----------------------------
-- Table structure for slimerace_log
-- ----------------------------
CREATE TABLE `slimerace_log` (
  `uid` int(10) NOT NULL,
  `search_item` int(10) unsigned NOT NULL,
  PRIMARY KEY (`uid`)
) ENGINE=MyISAM AUTO_INCREMENT=2 DEFAULT CHARSET=utf8;

-- ----------------------------
-- Table structure for sprite_frame
-- ----------------------------
CREATE TABLE `sprite_frame` (
  `name` varchar(255) NOT NULL DEFAULT '',
  `gfx` int(10) unsigned NOT NULL DEFAULT '0',
  `action` int(10) unsigned NOT NULL DEFAULT '0',
  `action_name` varchar(255) NOT NULL DEFAULT '',
  `frame` int(10) unsigned NOT NULL DEFAULT '0',
  PRIMARY KEY (`gfx`,`action`),
  KEY `id` (`gfx`),
  KEY `type` (`name`)
) ENGINE=MyISAM AUTO_INCREMENT=388 DEFAULT CHARSET=utf8;

-- ----------------------------
-- Table structure for user_behavior
-- ----------------------------
CREATE TABLE `user_behavior` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '主键',
  `ip` char(15) DEFAULT NULL COMMENT '操作者IP',
  `account` char(50) DEFAULT NULL COMMENT '账号',
  `operID` int(11) DEFAULT NULL COMMENT '角色ID',
  `operType` char(50) DEFAULT NULL COMMENT '操作类型',
  `targetID` char(12) DEFAULT NULL COMMENT '目标ID',
  `locX` int(11) DEFAULT NULL COMMENT '角色坐标X',
  `locY` int(11) DEFAULT NULL COMMENT '角色坐标Y',
  `locMap` int(11) DEFAULT NULL COMMENT '角色坐标地图编号',
  `operTime` datetime DEFAULT NULL COMMENT '操作时间',
  `remark` char(200) DEFAULT NULL COMMENT '其他备注',
  PRIMARY KEY (`id`),
  KEY `id` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='用户行为记录';

-- ----------------------------
-- Table structure for warehouse
-- ----------------------------
CREATE TABLE `warehouse` (
  `uid` int(10) unsigned NOT NULL AUTO_INCREMENT,
